if(window.top!==window.self){window.top.location=window.self.location;}document.addEventListener('contextmenu',function(e){if(e.target.tagName==='IMG' || e.target.closest('.gallery-card')|| e.target.closest('.lightbox-img-wrapper')|| e.target.closest('.hero-slider-img-wrap')){e.preventDefault();return false;}},false);document.addEventListener('dragstart',function(e){if(e.target.tagName==='IMG'){e.preventDefault();return false;}},false);document.addEventListener('DOMContentLoaded',()=>{initHeader();initHeroSlider();initProcessTabs();initProductGallery();initLightbox();initContactForm();});function initHeader(){const header=document.querySelector('.site-header');const toggleBtn=document.querySelector('.mobile-menu-toggle');const mainNav=document.querySelector('.main-nav');const navLinks=document.querySelectorAll('.nav-link');window.addEventListener('scroll',()=>{if(window.scrollY>20){header?.classList.add('scrolled');}else{header?.classList.remove('scrolled');}});toggleBtn?.addEventListener('click',()=>{mainNav?.classList.toggle('open');const isOpen=mainNav?.classList.contains('open');toggleBtn.setAttribute('aria-expanded',isOpen);});navLinks.forEach(link=>{link.addEventListener('click',()=>{mainNav?.classList.remove('open');});});}function initHeroSlider(){const slides=document.querySelectorAll('.hero-slide');const dots=document.querySelectorAll('.slider-dot');const prevBtn=document.querySelector('.slider-arrow-btn.prev');const nextBtn=document.querySelector('.slider-arrow-btn.next');if(!slides.length)return;let currentIndex=0;let timer=null;function showSlide(index){if(index<0)index=slides.length-1;if(index>=slides.length)index=0;currentIndex=index;slides.forEach((s,i)=>{s.classList.toggle('active',i===currentIndex);});dots.forEach((d,i)=>{d.classList.toggle('active',i===currentIndex);});}function startAutoPlay(){stopAutoPlay();timer=setInterval(()=>{showSlide(currentIndex+1);},4500);}function stopAutoPlay(){if(timer)clearInterval(timer);}prevBtn?.addEventListener('click',()=>{showSlide(currentIndex-1);startAutoPlay();});nextBtn?.addEventListener('click',()=>{showSlide(currentIndex+1);startAutoPlay();});dots.forEach((dot,i)=>{dot.addEventListener('click',()=>{showSlide(i);startAutoPlay();});});const sliderCard=document.querySelector('.hero-slider-card');sliderCard?.addEventListener('mouseenter',stopAutoPlay);sliderCard?.addEventListener('mouseleave',startAutoPlay);startAutoPlay();}function initProcessTabs(){const tabBtns=document.querySelectorAll('.process-tab-btn');const tabPanes=document.querySelectorAll('.process-tab-pane');if(!tabBtns.length)return;tabBtns.forEach(btn=>{btn.addEventListener('click',()=>{const targetId=btn.getAttribute('data-target');tabBtns.forEach(b=>b.classList.remove('active'));tabPanes.forEach(p=>p.classList.remove('active'));btn.classList.add('active');const targetPane=document.getElementById(targetId);if(targetPane){targetPane.classList.add('active');}});});}function initProductGallery(){const filterBtns=document.querySelectorAll('.filter-btn');const galleryCards=document.querySelectorAll('.gallery-card');if(!filterBtns.length)return;filterBtns.forEach(btn=>{btn.addEventListener('click',()=>{const category=btn.getAttribute('data-filter');filterBtns.forEach(b=>b.classList.remove('active'));btn.classList.add('active');galleryCards.forEach(card=>{const cardCat=card.getAttribute('data-category');if(category==='all' || cardCat===category){card.style.display='flex';}else{card.style.display='none';}});});});}let activeLightboxIndex=0;let currentLightboxImages=[];function initLightbox(){const modal=document.querySelector('.lightbox-modal');const modalImg=modal?.querySelector('img');const modalTitle=modal?.querySelector('.lightbox-caption h3');const modalDesc=modal?.querySelector('.lightbox-caption p');const closeBtn=modal?.querySelector('.lightbox-close');const prevBtn=modal?.querySelector('.lightbox-prev');const nextBtn=modal?.querySelector('.lightbox-next');if(!modal)return;function updateModalImage(index){if(!currentLightboxImages.length)return;if(index<0)index=currentLightboxImages.length-1;if(index>=currentLightboxImages.length)index=0;activeLightboxIndex=index;const item=currentLightboxImages[activeLightboxIndex];if(modalImg)modalImg.src=item.src;if(modalTitle)modalTitle.textContent=item.title || 'Sacerdoti Gráfica';if(modalDesc)modalDesc.textContent=item.category || 'Muestra de Producto';}function openLightbox(imagesList,index){currentLightboxImages=imagesList;updateModalImage(index);modal.classList.add('active');document.body.style.overflow='hidden';}function closeLightbox(){modal.classList.remove('active');document.body.style.overflow='';}closeBtn?.addEventListener('click',closeLightbox);prevBtn?.addEventListener('click',()=>updateModalImage(activeLightboxIndex-1));nextBtn?.addEventListener('click',()=>updateModalImage(activeLightboxIndex+1));modal.addEventListener('click',(e)=>{if(e.target===modal)closeLightbox();});document.addEventListener('keydown',(e)=>{if(!modal.classList.contains('active'))return;if(e.key==='Escape')closeLightbox();if(e.key==='ArrowLeft')updateModalImage(activeLightboxIndex-1);if(e.key==='ArrowRight')updateModalImage(activeLightboxIndex+1);});const galleryItems=document.querySelectorAll('.gallery-card');const imagesData=Array.from(galleryItems).map(card=>{const img=card.querySelector('img');const title=card.querySelector('.gallery-card-title')?.textContent || '';const category=card.querySelector('.gallery-card-tag')?.textContent || '';return{src:img?.getAttribute('data-full')|| img?.src || '',title,category,element:card};});galleryItems.forEach((card,index)=>{card.addEventListener('click',()=>{openLightbox(imagesData,index);});});}function initContactForm(){const form=document.getElementById('contactForm');const successMsg=document.getElementById('formSuccessMsg');if(!form)return;form.addEventListener('submit',(e)=>{e.preventDefault();const name=form.querySelector('[name="nombre"]')?.value.trim();const email=form.querySelector('[name="email"]')?.value.trim();const mensaje=form.querySelector('[name="mensaje"]')?.value.trim();if(!name ||!email ||!mensaje){alert('Por favor complete los campos obligatorios(Nombre,Email y Mensaje).');return;}const submitBtn=form.querySelector('button[type="submit"]');const originalText=submitBtn.innerHTML;submitBtn.innerHTML='Enviando consulta...';submitBtn.disabled=true;setTimeout(()=>{form.reset();submitBtn.innerHTML=originalText;submitBtn.disabled=false;if(successMsg){successMsg.style.display='block';successMsg.scrollIntoView({behavior:'smooth',block:'nearest'});setTimeout(()=>{successMsg.style.display='none';},8000);}},800);});}